module tall_enterprises (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] num_employees,\n    \n    input wire [19:0] id_0,\n    input wire [19:0] id_1,\n    input wire [19:0] id_2,\n    input wire [19:0] id_3,\n    \n    input wire [23:0] salary_0,\n    input wire [23:0] salary_1,\n    input wire [23:0] salary_2,\n    input wire [23:0] salary_3,\n    \n    input wire [23:0] height_0,\n    input wire [23:0] height_1,\n    input wire [23:0] height_2,\n    input wire [23:0] height_3,\n    \n    input wire [19:0] query_id,\n    input wire query_valid,\n    \n    output reg [19:0] boss_id,\n    output reg [7:0] num_subordinates,\n    output reg done,\n    output reg valid,\n    output reg ready\n);\n\n// State definitions\nlocalparam [2:0] IDLE             = 3'b000;\nlocalparam [2:0] SORT             = 3'b001;\nlocalparam [2:0] FIND_BOSS        = 3'b010;\nlocalparam [2:0] COMPUTE_SUB      = 3'b011;\nlocalparam [2:0] COMPUTE_BOSS_ORG = 3'b100;\nlocalparam [2:0] WAIT_QUERY       = 3'b101;\nlocalparam [2:0] QUERY            = 3'b110;\n\nreg [2:0] state;\nreg [2:0] next_state;\n\n// Internal data storage\nreg [19:0] id_reg [0:3];\nreg [23:0] salary_reg [0:3];\nreg [23:0] height_reg [0:3];\n\n// Working registers\nreg [1:0] sorted_idx [0:3];\nreg [1:0] boss_sorted [0:3];\nreg [7:0] sub_count [0:3];\nreg [19:0] boss_original [0:3];\nreg [7:0] sub_count_orig [0:3];\n\n// Counters and flags\nreg [1:0] i, j, k, l;\nreg [1:0] orig_idx;\nreg found;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        // Initialize all registers\n        state <= IDLE;\n        ready <= 1'b0;\n        valid <= 1'b0;\n        done  <= 1'b0;\n        boss_id <= 20'd0;\n        num_subordinates <= 8'd0;\n        \n        // Initialize arrays\n        for (integer m = 0; m < 4; m = m + 1) begin\n            id_reg[m] <= 20'd0;\n            salary_reg[m] <= 24'd0;\n            height_reg[m] <= 24'd0;\n            sorted_idx[m] <= 2'd0;\n            boss_sorted[m] <= 2'd0;\n            sub_count[m] <= 8'd0;\n            boss_original[m] <= 20'd0;\n            sub_count_orig[m] <= 8'd0;\n        end\n        \n        i <= 2'd0;\n        j <= 2'd0;\n        k <= 2'd0;\n        l <= 2'd0;\n        orig_idx <= 2'd0;\n        found <= 1'b0;\n    end else begin\n        case (state)\n            IDLE: begin\n                ready <= 1'b0;\n                done  <= 1'b0;\n                valid <= 1'b0;\n                if (start) begin\n                    // Store inputs\n                    id_reg[0] <= id_0;\n                    id_reg[1] <= id_1;\n                    id_reg[2] <= id_2;\n                    id_reg[3] <= id_3;\n                    salary_reg[0] <= salary_0;\n                    salary_reg[1] <= salary_1;\n                    salary_reg[2] <= salary_2;\n                    salary_reg[3] <= salary_3;\n                    height_reg[0] <= height_0;\n                    height_reg[1] <= height_1;\n                    height_reg[2] <= height_2;\n                    height_reg[3] <= height_3;\n                    \n                    // Initialize sorted indices\n                    sorted_idx[0] <= 2'd0;\n                    sorted_idx[1] <= 2'd1;\n                    sorted_idx[2] <= 2'd2;\n                    sorted_idx[3] <= 2'd3;\n                    \n                    // Reset counters\n                    i <= 2'd0;\n                    j <= 2'd0;\n                    k <= 2'd0;\n                    l <= 2'd0;\n                    state <= SORT;\n                end\n            end\n            \n            SORT: begin // Bubble sort by salary\n                if (i < num_employees) begin\n                    if (j < (num_employees - i - 2'd1)) begin\n                        if (salary_reg[sorted_idx[j]] > salary_reg[sorted_idx[j+1]]) begin\n                            sorted_idx[j] <= sorted_idx[j+1];\n                            sorted_idx[j+1] <= sorted_idx[j];\n                        end\n                        j <= j + 2'd1;\n                    end else begin\n                        j <= 2'd0;\n                        i <= i + 2'd1;\n                    end\n                end else begin\n                    i <= 2'd0;\n                    j <= 2'd0;\n                    k <= 2'd0;\n                    state <= FIND_BOSS;\n                end\n            end\n            \n            FIND_BOSS: begin\n                if (k == num_employees) begin\n                    k <= 2'd0;\n                    state <= COMPUTE_SUB;\n                end else if (l == num_employees) begin\n                    boss_sorted[k] <= 2'b11; // No boss\n                    k <= k + 2'd1;\n                    l <= k + 2'd1;\n                end else begin\n                    if ((l > k) && (height_reg[sorted_idx[l]] >= height_reg[sorted_idx[k]])) begin\n                        boss_sorted[k] <= l;\n                        k <= k + 2'd1;\n                        l <= k + 2'd1;\n                    end else begin\n                        l <= l + 2'd1;\n                    end\n                end\n            end\n            \n            COMPUTE_SUB: begin\n                if (k == num_employees) begin\n                    k <= 2'd0;\n                    state <= COMPUTE_BOSS_ORG;\n                end else begin\n                    if (boss_sorted[k] != 2'b11) begin\n                        sub_count[boss_sorted[k]] <= sub_count[boss_sorted[k]] + 8'd1 + sub_count[k];\n                    end\n                    k <= k + 2'd1;\n                end\n            end\n            \n            COMPUTE_BOSS_ORG: begin\n                if (k < num_employees) begin\n                    orig_idx <= sorted_idx[k];\n                    boss_original[sorted_idx[k]] <= (boss_sorted[k] == 2'b11) ? 20'd0 : id_reg[sorted_idx[boss_sorted[k]]];\n                    sub_count_orig[sorted_idx[k]] <= sub_count[k];\n                    k <= k + 2'd1;\n                end else begin\n                    ready <= 1'b1;\n                    state <= WAIT_QUERY;\n                    done <= 1'b1;\n                end\n            end\n            \n            WAIT_QUERY: begin\n                done <= 1'b0;\n                valid <= 1'b0;\n                if (query_valid) begin\n                    ready <= 1'b0;\n                    k <= 2'd0;\n                    found <= 1'b0;\n                    state <= QUERY;\n                end\n            end\n            \n            QUERY: begin\n                if (k < num_employees) begin\n                    if (id_reg[k] == query_id) begin\n                        boss_id <= boss_original[k];\n                        num_subordinates <= sub_count_orig[k];\n                        found <= 1'b1;\n                    end\n                    k <= k + 2'd1;\n                end else begin\n                    valid <= 1'b1;\n                    if (!found) begin\n                        boss_id <= 20'd0;\n                        num_subordinates <= 8'd0;\n                    end\n                    ready <= 1'b1;\n                    state <= WAIT_QUERY;\n                end\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule